@web.route("/mountain/ranges")
def mountainranges():
    driver = webdriver.Chrome()
    list = []

    n = 0
    try:
        string = "https://www.mountain-forecast.com/mountain_ranges"
        driver.get(string)
        time.sleep(5)
        html = driver.page_source
        soup = BeautifulSoup(html, 'lxml')
        maindiv = soup.find("div", attrs={"class": "body-content"})
        ul = maindiv.find("ul",attrs = {"class":"b-list-table"})
        lis = ul.select("li")
        for alin in lis:
            a = alin.find("a")
            spannnumber = alin.find("span",attrs = {"class":"b-list-table__item-num"})
            if a is not None:
                list.append(a.attrs["href"])
            if spannnumber is not None:
                number = int(spannnumber.text.strip())
                n = n + number

    except Exception as e:
        print(e)

    driver.quit()

    return json.dumps(list)
    return "done"

