@web.route("/mountian/location")
def mountainlocation():
    image_path = os.path.join(basedir, 'static/meteoblue', "mountainstation2.json")
    f = open(image_path, "r")
    mlist = json.loads(f.read())

    # options = Options()
    # # options.page_load_strategy = 'none'
    # options.page_load_strategy = 'eager'
    # options.add_argument('--disable-browser-side-navigation')
    # # options.page_load_strategy = 'normal'
    # driver = webdriver.Chrome(options=options)

    n = 0
    m = 0



    for mdict in mlist:
        try:


            link = mdict["href"]

            if "latitude" in mdict:
                m = m + 1
                continue
            else:
                time.sleep(1)
                n = n + 1
                if n > 2000:
                    break

            string = "https://www.mountain-forecast.com" + link
            response = requests.get(string)
            html = response.text

            # html = driver.page_source
            soup = BeautifulSoup(html, 'html.parser')
            maindiv = soup.find("main", attrs={"class": "main-content"})
            latituede = maindiv.find("span",attrs = {"class":"latitude"})
            longitude = maindiv.find("span",attrs = {"class":"longitude"})
            mdict["latitude"] = latituede.attrs["title"]
            mdict["longitude"] = longitude.attrs["title"]
            elevationlist = maindiv.find("ul",attrs = {"class":"forecast-table-elevation__list"})
            lis = elevationlist.select("li")
            elist = []
            for li in lis:
                a =  li.find("a")
                if a is not  None:
                    elist.append(a.attrs["data-elevation-level"])
            mdict["elevation"] = elist



        except Exception as e :
            print(e)

    image_path = os.path.join(basedir, 'static/meteoblue', "mountainstation2.json")
    f = open(image_path, "w")
    f.write(json.dumps(mlist))
    f.close()



    # driver.quit()

    return "done"

